use std::collections::VecDeque;

fn count_lakes(grid: Vec<Vec<char>>) -> (u32, u32) {
    let rows = grid.len();
    let cols = if rows > 0 { grid[0].len() } else { 0 };
    let mut seen = vec![vec![false; cols]; rows];
    let (mut count, mut largest) = (0u32, 0u32);
    for r in 0..rows {
        for c in 0..cols {
            if grid[r][c] != '~' || seen[r][c] {
                continue;
            }
            // A new lake: flood it breadth-first with an explicit queue.
            count += 1;
            let mut size = 0u32;
            seen[r][c] = true;
            let mut queue = VecDeque::from([(r, c)]);
            while let Some((y, x)) = queue.pop_front() {
                size += 1;
                // wrapping_sub turns "one before 0" into usize::MAX, which the
                // bounds check below rejects.
                for (ny, nx) in [(y + 1, x), (y.wrapping_sub(1), x), (y, x + 1), (y, x.wrapping_sub(1))] {
                    if ny < rows && nx < cols && grid[ny][nx] == '~' && !seen[ny][nx] {
                        seen[ny][nx] = true;
                        queue.push_back((ny, nx));
                    }
                }
            }
            largest = largest.max(size);
        }
    }
    (count, largest)
}
